-- discounting-exercise-3
insert into public.items (slug, kind, title, summary, owner_id, stored_at, duration_seconds, origin, source) values ('discounting-exercise-3', 'video', 'Discounting Exercise 3', 'Walks through building a future value model in Excel, writing a compounding
formula that multiplies a cash flow by (1 + r)^T to calculate the future
value of a payment occurring at time zero.', (select id from public.owners where slug = 'not-established'), 'https://player.vimeo.com/video/1192297219?dnt=1', 180, 'primitive', 'myrumbo:excel-for-finance (WhisperX transcript, Vimeo upload)');
insert into public.items (slug, kind, title, summary, owner_id, body_md, origin, derived_from, source) values ('discounting-exercise-3--read', 'read', 'Discounting Exercise 3: reading', 'Walks through building a future value model in Excel, writing a compounding
formula that multiplies a cash flow by (1 + r)^T to calculate the future
value of a payment occurring at time zero.', (select id from public.owners where slug = 'not-established'), '## The future value formula

To compound a cash flow forward in time, multiply the present value by
(1 + r) raised to the power T, where r is the discount rate and T is
the number of periods you are compounding forward. A payment of $1
today is worth (1 + r)^T dollars at time T.

## Building the model

Set up a year column that records when each cash flow actually occurs.
In this exercise, a single cash flow occurs at year zero and you are
compounding it one period forward to year one.

Break the formula into two parts. First, calculate the compounding
factor: 1 plus the discount rate, raised to the power of the
destination period. Anchor the discount rate cell with dollar signs
($B$2 style) so it stays fixed if you copy the formula. Second,
multiply the payment by that compounding factor to get the future
value.

## Keeping the model dynamic

Point your answer cell directly at the formula result rather than
hard-coding a number. That way, when you change any input — the
payment amount or the discount rate — the future value updates
automatically. This is the core habit of good financial modelling:
inputs live in dedicated cells, and every output traces back to
those inputs through formulas.', 'derived', (select id from public.items where slug = 'discounting-exercise-3'), 'myrumbo descriptor prompt (read_content)');
