-- discounting-exercise-5
insert into public.items (slug, kind, title, summary, owner_id, stored_at, duration_seconds, origin, source) values ('discounting-exercise-5', 'video', 'Discounting Exercise 5', 'Walks through Exercise 5, adapting a discounting model from annual to monthly
cash flows by dividing the annual rate by 12, using SEQUENCE to generate 120
periods, and summing the final column to get the present value.', (select id from public.owners where slug = 'not-established'), 'https://player.vimeo.com/video/1192297277?dnt=1', 139, 'primitive', 'myrumbo:excel-for-finance (WhisperX transcript, Vimeo upload)');
insert into public.items (slug, kind, title, summary, owner_id, body_md, origin, derived_from, source) values ('discounting-exercise-5--read', 'read', 'Discounting Exercise 5: reading', 'Walks through Exercise 5, adapting a discounting model from annual to monthly
cash flows by dividing the annual rate by 12, using SEQUENCE to generate 120
periods, and summing the final column to get the present value.', (select id from public.owners where slug = 'not-established'), '## Adapting a discounting model to monthly cash flows

When cash flows occur monthly rather than annually, two things must
change: the number of periods and the discount rate. For 10 years of
monthly payments, you need 120 periods (10 × 12). Your annual discount
rate — 4.3% here — must be divided by 12 to get a monthly equivalent
before it can be used in the present value calculation.

## Generating the period sequence

Use SEQUENCE to build the period index automatically. Pass it 120 rows
and 1 column, starting at 0, so the series runs from month 0 to
month 119. Starting at 0 rather than 1 matters because the exponent
in the future-value factor depends on how many months remain, not
which month you''re in.

## Anchoring references and filling down

The discount rate cell must be anchored with an absolute reference
($B$2 or equivalent) so it stays fixed as formulas copy down the
column. To anchor quickly: press F2 to enter the cell, cursor to the
reference, and press F4 to add the dollar signs.

Once the first row is correct, select the entire block — all three
columns — with Ctrl+Shift+Up, then press Ctrl+D to fill every row
down in one step. The final answer is the SUM of the last column,
which contains the present value of each individual monthly cash flow.', 'derived', (select id from public.items where slug = 'discounting-exercise-5'), 'myrumbo descriptor prompt (read_content)');
